            const checkedTags = Array.from(document.querySelectorAll('.tag-check:checked')).map(el => el.value);
            const hashtagString = checkedTags.length > 0 ? '\\n\\n' + checkedTags.join(' ') : '';

            // Appends selected hashtags natively to existing content variations dynamically if chosen
            // For a highly production-ready environment, we track base string vs attached string, 
            // but for a lightweight tool we simply compute live differences or allow direct editing.
