            const text = document.getElementById(`text${id}`).value;

            // Character count
            document.getElementById(`count${id}`).innerText = `${text.length} / 2200 chars`;

            // CTA Warning detection (looks for keyword variations like link, bio, profile, comment, dm)
            const hasCTAKeywords = /link|bio|profile|comment|dm|drop|click/i.test(text);
            const warningBar = document.getElementById(`warning${id}`);

            if (!hasCTAKeywords && text.trim().length > 0) {
                warningBar.style.display = 'block';
            } else {
                warningBar.style.display = 'none';
            }
        }

        function copyCaption(id) {
            const textarea = document.getElementById(`text${id}`);
            textarea.select();
            textarea.setSelectionRange(0, 99999); // Mobile compatibility

            navigator.clipboard.writeText(textarea.value).then(() => {
                const copyBtn = document.getElementById(`copy${id}`);
                const originalText = copyBtn.innerHTML;
                copyBtn.innerHTML = '✅ Copied!';
                copyBtn.classList.add('success');

                setTimeout(() => {
                    copyBtn.innerHTML = originalText;
                    copyBtn.classList.remove('success');
                }, 2000);
            });
        }

        function exportText(id) {
            const text = document.getElementById(`text${id}`).value;
            const blob = new Blob([text], { type: 'text/plain;charset=utf-8' });
            const link = document.createElement('a');
            link.href = URL.createObjectURL(blob);
            link.download = `instagram-caption-option-${id.toLowerCase()}.txt`;
            link.click();
            URL.revokeObjectURL(link.href);
        }
    </script>
</body>
</html>
